slides.base:
.sidebar { background: var(--role-sidebar); color: var(--role-sidebar-ink); }
.sidebar-toggle { background: var(--role-sidebar); color: var(--role-sidebar-ink); }
.sidebar-collapse-btn { background: rgba(var(--role-sidebar-ink-rgb), 0.15); color: var(--role-sidebar-ink); }
.sidebar-title, .resources-title, .chapter-header, .slide-item, .resource-link { color: var(--role-sidebar-ink); }
.chapter-header:hover, .slide-item:hover, .resource-link:hover { background: transparent; color: var(--role-sidebar-ink); text-decoration: underline; }
.chapter-item.active > .chapter-header { background: transparent; color: var(--role-sidebar-ink); border-left-color: var(--role-accent); font-weight: 600; }
.slide-item.active { background: transparent; color: var(--role-sidebar-ink); box-shadow: inset 3px 0 0 var(--role-accent); font-weight: 600; }
.main { background-color: var(--role-content-background); }
.slide h2 { color: var(--role-heading); }
.slide p { color: var(--role-body); }
.divider { background: var(--role-accent); }
.card h4 { color: var(--role-heading); }
.card p, .content-list li { color: var(--role-body); }
.content-list li::before { color: var(--role-accent); }
.download-btn, .video-btn { background: var(--role-button); color: var(--role-button-ink); }
.slide-title h1 { color: var(--role-title-text); }
.slide-title .subtitle, .slide-title .copyright { color: var(--role-subtitle); }
.slide-title .divider { background: var(--role-accent); }
.slide-section, .slide-section[data-chapter-num] { background: var(--role-divider-background); }
.slide-section h2, .slide-section .chapter-label { color: var(--role-divider-background-ink); }
.slide-section .divider { background: var(--role-accent); }
.slide-section .section-circle { border-color: rgba(var(--role-divider-background-ink-rgb), 0.25); }
.slide-section::after { color: rgba(var(--role-divider-background-ink-rgb), 0.06); }
.slide-video h2 { color: var(--role-heading); }
.activity-box { border-color: var(--role-accent); }
.activity-label { color: var(--role-heading); }
.activity-box p { color: var(--role-body); }

options.css:
.slide-title { background: var(--role-content-background); }
.slide-title h1 { color: var(--role-heading); }
.slide-title .subtitle, .slide-title .copyright { color: var(--role-body); }

.slide-title { flex-direction: column; align-items: flex-start; justify-content: center; text-align: left; background: none; position: relative; z-index: 1; }
.slide-title::before { content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 40%; background: var(--role-title-background); z-index: -1; flex: none; display: block; }
.slide-title::after { content: ''; position: absolute; left: 40%; top: 0; bottom: 0; right: 0; background: var(--role-title-background-end); z-index: -1; flex: none; display: block; }
.slide-title .logo { max-width: 220px; margin: 0 0 1.5rem; }
.slide-title h1 { max-width: 90%; margin: 0; }
.slide-title .divider { margin: 1.5rem 0; }
.slide-title .subtitle { max-width: 90%; margin-bottom: 0; }
.slide-title .copyright { position: absolute; bottom: 2rem; left: 5rem; margin: 0; }

.slide-section, .slide-section[data-chapter-num] { background: var(--role-content-background); }
.slide-section h2 { color: var(--role-heading); }
.slide-section .chapter-label { color: var(--role-body); }
.slide-section .section-circle { border-color: rgba(var(--role-accent-rgb), 0.35); }
.slide-section::after { color: rgba(var(--role-heading-rgb), 0.06); }

.slide-section, .slide-section[data-chapter-num] { background: var(--role-content-background); }
.slide-section::before { content: ''; position: absolute; left: 0; right: 0; top: 30%; height: 40%; background: var(--role-divider-background); flex: none; display: block; z-index: 0; }
.slide-section > * { position: relative; z-index: 1; }
.slide-section .section-circle { display: none; }

.slide-section { align-items: flex-start; justify-content: flex-end; text-align: left; padding: 0 8rem 6rem; }
.slide-section .section-circle { display: none; }
.slide-section::after { left: 6%; right: auto; top: 4%; bottom: auto; transform: none; font-size: 18rem; }

.slide-video.active { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); align-content: center; align-items: center; gap: 3rem; text-align: left; }
.slide-video.active::before, .slide-video.active::after { display: none; }
.slide-video h2 { margin: 0; }

.cards-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.25rem; }
.card { padding: 1.25rem 1.5rem; }
.card h4 { font-size: 1.45rem; }
.card p { font-size: 1.2rem; }

.cards-grid { grid-template-columns: 1fr; gap: 0.75rem; }
.card { flex-direction: row; align-items: baseline; gap: 2rem; padding: 1rem 2rem; text-align: left; }
.card h4 { flex: 0 0 32%; margin: 0; text-align: left; }
.card p { margin: 0; text-align: left; }

.cards-grid { counter-reset: spokes-card; }
.card { position: relative; padding: 1.5rem 2rem 1.5rem 4.75rem; }
.card::before { counter-increment: spokes-card; content: counter(spokes-card); position: absolute; left: 1.5rem; top: 1.4rem; font-family: var(--font-heading); font-size: 2.2rem; line-height: 1; color: var(--role-heading); }

.activity-box { background: var(--role-content-background); }
.activity-label { color: var(--role-heading); }
.activity-box p { color: var(--role-body); }

.activity-box { background: rgba(var(--role-accent-rgb), 0.1); }
.activity-label { color: var(--role-heading); }
.activity-box p { color: var(--role-body); }

.activity-box { display: grid; grid-template-columns: minmax(0, 12rem) minmax(0, 1fr); gap: 0 2rem; align-items: baseline; border: 2px solid var(--role-accent); border-radius: 12px; }
.activity-label { margin: 0; }
.activity-box > :not(.activity-label) { grid-column: 2; }
